sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float speed;
uniform float amount;
uniform float tilt;
uniform float squash;
uniform float sway;
half4 main(float2 coord) {
    float t = time * max(speed, 0.001) * 6.2831853;
    float bob = sin(t) * amount;
    float side = cos(t * 0.5) * sway;
    float angle = radians(sin(t) * tilt);
    float2 p = coord / max(size, float2(1.0)) - 0.5;
    float s = 1.0 + sin(t * 2.0) * squash;
    p.x /= max(s, 0.1);
    p.y *= s;
    float ca = cos(angle), sa = sin(angle);
    p = float2(p.x * ca - p.y * sa, p.x * sa + p.y * ca) + 0.5;
    p += float2(side, bob);
    return image.eval(clamp(p, 0.0, 1.0) * size);
}
